window.WOLFIE_CONTEXT_PACKS=(window.WOLFIE_CONTEXT_PACKS||[]).concat([{"id":"mission-v2-010","day":10,"level":"A2","title":"A new neighbour at the door","ru":"Новый сосед","goal":"Представиться, рассказать о доме и вежливо предложить помощь.","version":1,"profile":"extended-v1","quality":"authored-not-independently-reviewed","grammar":{"title":"There is / there are","rule":"There is употребляется с единственным числом и неисчисляемыми существительными; there are — с множественным. Для отрицания добавь not; для вопроса поставь is/are перед there.","pattern":"There is a lift; There are two entrances; Is there a shop?","example":"There is a notice beside the entrance.","pitfall":"Не говори There are a lift. Согласуй be с существительным.","exercises":[["choice","___ a lift in this building.",["There is","There are","There be"],0,"A lift — единственное число."],["type","Complete: There ___ two entrances.",["are"],"Two entrances — множественное число."],["order","Составь: Есть ли магазин поблизости?",["nearby","shop","a","there","Is"],"Is there a shop nearby","В вопросе is перед there."],["choice","There ___ any free parking spaces.",["isn't","aren't","doesn't"],1,"Spaces — множественное число."],["type","Complete: There is ___ elevator next to the stairs. Use a or an.",["an"],"Elevator начинается с гласного звука."],["order","Составь: На первом этаже есть две двери.",["floor","ground","the","on","doors","two","are","There"],"There are two doors on the ground floor","There are + plural noun."]]},"words":[["a doorbell","дверной звонок"],["a building entrance","вход в здание"],["a stairwell","лестничная клетка"],["a nameplate","табличка с именем"],["a ground-floor flat","квартира на первом этаже"],["a moving box","коробка для переезда"],["a spare key","запасной ключ"],["a nearby bakery","пекарня поблизости"],["a residents' noticeboard","доска объявлений жильцов"],["a building caretaker","смотритель здания"]],"phrases":[["I have just moved in.","Я только что переехал."],["Which entrance should I use?","Каким входом мне пользоваться?"],["There is a bakery around the corner.","За углом есть пекарня."],["Are there any shops nearby?","Есть ли поблизости магазины?"],["Let me show you where the lift is.","Покажу, где находится лифт."],["Do you need a hand with those boxes?","Помочь с этими коробками?"],["That's very kind of you.","Это очень любезно с твоей стороны."],["The noticeboard is beside the stairs.","Доска объявлений возле лестницы."],["Please let me know if you need anything.","Сообщи, если что-нибудь понадобится."],["I hope you settle in quickly.","Надеюсь, ты быстро освоишься."]],"reading":{"title":"A new neighbour at the door","paragraphs":["On a rainy Tuesday, a new neighbour moves into a flat on the second floor. His name is Alex. He has several boxes, but he cannot find the lift because the main entrance has two corridors. Nina sees him near the stairs and introduces herself. She tells him that there is a lift behind the noticeboard and that there are two entrances to the building. Alex thanks her and carries his boxes upstairs.","Later, Nina meets Alex outside the building. He asks whether there is a shop nearby. She explains that a small bakery is around the corner and a larger shop is across the road. Alex says that he can find them now. Nina offers to show him the residents' noticeboard, where there are useful phone numbers and information about shared spaces. They say goodbye and agree to say hello whenever they meet. Nina does not ask him for private details; she simply offers practical help."],"questions":[["Why is Alex confused?",["He cannot find the lift","He lost a phone","He cannot open a shop"],0],["Where is the bakery?",["Across the lake","Around the corner","On the second floor"],1],["What is on the noticeboard?",["Only photographs","A list of holidays","Useful building information"],2],["How does Nina make the meeting comfortable?",["She offers practical help without private questions","She asks for his financial details","She insists on visiting his flat"],0]]},"dialogue":[["Nina","Hello, I'm Nina. Have you just moved in?","Привет, я Нина. Ты только что переехал?"],["Alex","Yes, I'm Alex. I'm looking for the lift.","Да, я Алекс. Ищу лифт."],["Nina","There is a lift behind the noticeboard.","Лифт за доской объявлений."],["Alex","Thank you. Are there any shops nearby?","Спасибо. Есть поблизости магазины?"],["Nina","There's a bakery around the corner.","За углом есть пекарня."],["Alex","Great. I'll go there later.","Отлично. Схожу туда позже."],["Nina","Do you need a hand with those boxes?","Помочь с коробками?"],["Alex","That's very kind. One box would be helpful.","Очень любезно. Помощь с одной коробкой была бы кстати."]],"listening":["Where is the lift?",["Behind the noticeboard","In the bakery","Outside the building"],0],"speaking":["Introduce yourself to a new neighbour and offer one practical piece of help.","Describe your imaginary building using two there is and two there are sentences.","Ask about nearby services without asking private questions.","Explain the location of a lift and a noticeboard.","Role-play accepting a kind offer while setting a clear limit."],"writing":["Write a friendly welcome note with two useful local details.","Write four questions about a fictional building's facilities.","Write a thank-you message after a neighbour helps you move."],"model":"Hello, welcome to the building! There is a lift behind the noticeboard, and there are two shops nearby. Please let me know if you need help finding them. I hope you settle in quickly."},{"id":"mission-v2-040","day":40,"level":"A2","title":"Checking a hotel bill","ru":"Проверка счёта в гостинице","goal":"Уточнить позиции в счёте, сверить сумму и вежливо сообщить о возможной ошибке.","version":1,"profile":"extended-v1","quality":"authored-not-independently-reviewed","grammar":{"title":"Some / any / no in service questions","rule":"Some обычно употребляется в утвердительных предложениях; any — в вопросах и отрицаниях; no — прямое отсутствие. Some также возможен в просьбах и предложениях, когда ожидается согласие.","pattern":"There are some charges; Are there any extra charges? There are no extra charges.","example":"Could I have some information about this charge?","pitfall":"Не сочетай no и not для одного обычного отрицания.","exercises":[["choice","Are there ___ extra charges?",["any","no any","some of"],0,"Any в нейтральном вопросе."],["type","Complete: There are ___ extra charges. Use no to mean zero.",["no"],"No + plural noun."],["order","Составь: У меня есть несколько вопросов.",["questions","some","have","I"],"I have some questions","Some в утверждении."],["choice","I haven't received ___ receipt.",["any","no","none of"],0,"Any после haven't."],["type","Complete: Could I have ___ information, please?",["some","more"],"Some — вежливая просьба; more тоже естественно."],["order","Составь: В счёте нет дополнительных сборов.",["bill","the","on","fees","extra","no","are","There"],"There are no extra fees on the bill","No выражает отсутствие."]]},"words":[["an itemised bill","детализированный счёт"],["a room charge","плата за номер"],["an additional charge","дополнительное начисление"],["a minibar entry","позиция мини-бара"],["a booking rate","тариф бронирования"],["a payment record","запись об оплате"],["a checkout desk","стойка выезда"],["a disputed item","спорная позиция"],["an invoice copy","копия счёта"],["a corrected total","исправленная итоговая сумма"]],"phrases":[["Could I see an itemised bill?","Можно посмотреть детализированный счёт?"],["I have a question about this charge.","У меня вопрос по этому начислению."],["I don't recognise this item.","Я не узнаю эту позицию."],["Was breakfast included in the room rate?","Завтрак входил в тариф номера?"],["Could you check the booking record?","Можете проверить запись бронирования?"],["I may have misunderstood the price.","Возможно, я неправильно понял цену."],["Are there any other fees?","Есть ли другие сборы?"],["Thank you for checking that.","Спасибо, что проверили."],["Please send me a corrected invoice.","Отправьте мне исправленный счёт."],["I'll pay once we have checked the total.","Оплачу после проверки итоговой суммы."]],"reading":{"title":"Checking a hotel bill","paragraphs":["Marta is checking out of a small hotel after two nights. At the desk, the receptionist gives her an itemised bill. Marta recognises the room charge and the breakfast charge, but she notices a separate minibar entry. She remembers bringing her own drinks and does not think she used the minibar. Instead of accusing the receptionist of making a mistake, she asks whether the entry can be checked. She also asks whether there are any other charges she should know about.","The receptionist opens the booking record and compares it with the list of room expenses. The minibar entry belongs to a different room with a similar number. The receptionist apologises, removes the incorrect entry and prints a corrected bill. Marta checks the new total and pays. She asks for a copy by email so she can keep a record of the payment. The situation is resolved because both people check the details rather than argue about an unexplained amount."],"questions":[["Which entry does Marta question?",["Breakfast","Minibar","Room charge"],1],["How does she raise the issue?",["She asks for a check","She refuses to speak","She accuses the hotel immediately"],0],["Where did the incorrect entry belong?",["A shop","A restaurant","A different room"],2],["What does Marta request after paying?",["A copy by email","A new room","Another breakfast"],0]]},"dialogue":[["Marta","Could I see the itemised bill, please?","Можно детализированный счёт?"],["Receptionist","Of course. Here are the room and other charges.","Конечно. Вот плата за номер и другие позиции."],["Marta","I don't recognise this minibar entry.","Я не узнаю эту позицию мини-бара."],["Receptionist","I'll check the room expense record.","Проверю запись расходов по номеру."],["Marta","Are there any other extra fees?","Есть ещё дополнительные сборы?"],["Receptionist","No. This entry belongs to another room.","Нет. Эта позиция относится к другому номеру."],["Marta","Thank you for checking. Could I have a corrected invoice?","Спасибо за проверку. Можно исправленный счёт?"],["Receptionist","Certainly. I'll email a copy as well.","Конечно. Также отправлю копию по почте."]],"listening":["What will the receptionist email?",["A corrected invoice","A room photograph","A breakfast menu"],0],"speaking":["Ask to see an itemised bill and explain one fictional unclear charge.","Use some, any and no in three hotel-service questions or statements.","Ask whether breakfast was included in a fictional room rate.","Role-play discussing a possible billing error without accusing anyone.","Confirm what information you want on a corrected invoice."],"writing":["Write a polite message questioning one fictional hotel charge.","Write a short confirmation of a corrected total without inventing payment.","Write an email asking for an invoice copy after a fictional stay."],"model":"Hello, I have a question about the minibar entry on my bill. I do not recognise the charge. Could you check the room expense record and confirm the corrected total? Thank you for your help."},{"id":"mission-v2-070","day":70,"level":"A2","title":"A message after a difficult day","ru":"Сообщение после трудного дня","goal":"Предложить поддержку, спросить о предпочтениях собеседника и не давить.","version":1,"profile":"extended-v1","quality":"authored-not-independently-reviewed","grammar":{"title":"Would rather / prefer","rule":"Would rather + начальная форма без to выражает предпочтение в конкретной ситуации; prefer + noun / -ing / to-infinitive выражает предпочтение. Would you rather A or B? — выбор между вариантами.","pattern":"I'd rather talk later; I prefer quiet evenings.","example":"Would you rather talk now or tomorrow?","pitfall":"Не говори I'd rather to talk.","exercises":[["choice","I'd rather ___ at home tonight.",["stay","to stay","staying"],0,"Would rather + base verb."],["type","Complete: I prefer ___ (walk) to driving.",["walking"],"Prefer -ing to -ing."],["order","Составь: Ты бы предпочёл поговорить завтра?",["tomorrow","talk","rather","you","Would"],"Would you rather talk tomorrow","Would you rather + verb?"],["choice","I would rather ___ discuss it now.",["not","don't","to not"],0,"Would rather not + verb."],["type","Complete: She prefers ___ (read) before bed.",["reading","to read"],"Both -ing and to-infinitive are possible here."],["order","Составь: Я предпочёл бы подождать.",["wait","rather","would","I"],"I would rather wait","Rather + verb."]]},"words":[["a tiring day","утомительный день"],["a quiet moment","спокойная минута"],["a supportive message","сообщение с поддержкой"],["a personal boundary","личная граница"],["a small favour","небольшая услуга"],["a listening ear","готовность выслушать"],["a difficult conversation","непростой разговор"],["a gentle reminder","мягкое напоминание"],["a free evening","свободный вечер"],["a mutual understanding","взаимопонимание"]],"phrases":[["Would you rather talk now or later?","Предпочитаешь поговорить сейчас или позже?"],["I can listen if you want to talk.","Могу выслушать, если захочешь поговорить."],["You don't have to reply straight away.","Не обязательно отвечать сразу."],["I'd rather have a quiet evening.","Я бы предпочёл спокойный вечер."],["Let me know what would help.","Скажи, что могло бы помочь."],["I don't want to put pressure on you.","Не хочу давить на тебя."],["We can talk about something lighter.","Можем поговорить о чём-нибудь полегче."],["Take your time with the reply.","Не торопись с ответом."],["I hope tomorrow feels a little easier.","Надеюсь, завтра будет немного легче."],["Thanks for understanding what I need.","Спасибо, что понимаешь, что мне нужно."]],"reading":{"title":"A message after a difficult day","paragraphs":["Lena has had a busy day at work and sends a short message to her friend Max. She says that she feels tired but does not explain everything that happened. Max wants to help, but he is not sure whether Lena wants advice or simply a quiet evening. He asks whether she would rather talk now or later. He also says that she does not need to reply straight away.","Lena answers that she would prefer to rest first. She might want to talk tomorrow, but she does not make a promise. Max accepts her answer and sends a short, friendly message. He does not ask the same question again or try to guess what caused her difficult day. The next afternoon Lena writes to him when she has time. They talk about her day and then change the subject to something lighter. Their conversation feels comfortable because both can say what they prefer."],"questions":[["What does Max want to find out?",["Whether Lena wants to talk now or later","How much she earns","Where she will move"],0],["What does Lena prefer first?",["A long phone call","Rest","Advice immediately"],1],["What does Max avoid doing?",["Accepting her answer","Sending a friendly message","Repeating the same question"],2],["Why does their conversation feel comfortable?",["They never disagree","They can express preferences","Max chooses everything"],1]]},"dialogue":[["Max","It sounds like you've had a tiring day.","Похоже, день был утомительным."],["Lena","Yes, I'd rather rest for a while.","Да, я бы предпочла немного отдохнуть."],["Max","Would you rather talk tomorrow?","Предпочитаешь поговорить завтра?"],["Lena","Maybe. I don't want to make a plan yet.","Возможно. Пока не хочу строить планы."],["Max","That's fine. You don't have to reply straight away.","Хорошо. Не обязательно отвечать сразу."],["Lena","Thanks. I appreciate that.","Спасибо. Ценю это."],["Max","We can talk about something lighter when you're ready.","Когда будешь готова, можем поговорить о чём-нибудь полегче."],["Lena","I'll let you know when I have time.","Сообщу, когда будет время."]],"listening":["What does Lena prefer right now?",["To rest","To make a detailed plan","To give advice"],0],"speaking":["Ask whether a fictional friend wants advice, conversation or time alone.","Express three personal preferences using would rather or prefer.","Respond politely when someone says they want to rest.","Offer support without asking for an immediate reply.","Role-play switching to a lighter topic after a difficult conversation."],"writing":["Write a brief supportive message to an imaginary friend.","Write a reply explaining that you prefer to talk later.","Write two alternative messages: one offering advice and one offering to listen."],"model":"I'm sorry your day was difficult. Would you rather talk now or rest for a while? I can listen if you want to talk, but you don't have to reply straight away. I hope tomorrow feels a little easier."},{"id":"mission-v2-100","day":100,"level":"A2","title":"A parcel return label","ru":"Этикетка для возврата посылки","goal":"Понять последовательность действий и запросить уточнение об отправлении.","version":1,"profile":"extended-v1","quality":"authored-not-independently-reviewed","grammar":{"title":"Sequence markers and imperatives","rule":"First, then, next, finally помогают описывать порядок. Для инструкций используй начальную форму глагола: check, attach, keep. Don't + verb — отрицательная инструкция.","pattern":"First check the label; then attach it; finally keep the receipt.","example":"Don't cover the barcode.","pitfall":"Не ставь to после don't в инструкции.","exercises":[["choice","First, ___ the return reference.",["check","to check","checking"],0,"Imperative: base verb."],["type","Complete: Don't ___ (cover) the barcode.",["cover"],"Don't + base verb."],["order","Составь: Затем прикрепи этикетку.",["label","the","attach","Then"],"Then attach the label","Then + imperative."],["choice","Which word introduces the last step?",["Finally","First","Before"],0,"Finally marks the end."],["type","Complete: Keep the receipt ___ you receive confirmation.",["until","till"],"Until/till indicates duration to an event."],["order","Составь: Не выбрасывай квитанцию.",["receipt","the","away","throw","not","Do"],"Do not throw away the receipt","Do not + verb."]]},"words":[["a return label","этикетка для возврата"],["a parcel drop-off point","пункт сдачи посылок"],["a barcode","штрихкод"],["a return reference","номер возврата"],["a padded envelope","мягкий конверт"],["a return confirmation","подтверждение возврата"],["a tracking update","обновление отслеживания"],["a collection receipt","квитанция о приёме"],["a packaging instruction","инструкция по упаковке"],["a return deadline","срок возврата"]],"phrases":[["I've received a return label by email.","Я получил этикетку возврата по почте."],["Where can I drop off this parcel?","Где можно сдать эту посылку?"],["Do I need to print the label?","Нужно распечатать этикетку?"],["First, check the return reference.","Сначала проверь номер возврата."],["Please keep the barcode visible.","Оставьте штрихкод видимым."],["Can you scan the label here?","Можете отсканировать этикетку здесь?"],["I'd like a receipt for the drop-off.","Мне нужна квитанция о сдаче."],["The parcel has been accepted for transport.","Посылку приняли к перевозке."],["I haven't received the final confirmation yet.","Окончательного подтверждения пока нет."],["I'll keep the receipt until the return is complete.","Сохраню квитанцию до завершения возврата."]],"reading":{"title":"A parcel return label","paragraphs":["Ben orders a jacket online, but it does not fit. The shop sends him a return label and explains where he can drop off the parcel. Ben reads the message carefully because he has not returned anything to this shop before. First, he checks the return reference. Then he puts the jacket in suitable packaging and attaches the label. He makes sure that the barcode is visible and takes the parcel to a local drop-off point.","The worker at the counter scans the label and gives Ben a receipt. Ben asks whether this means that the shop has already received the jacket. The worker explains that the receipt only confirms that the parcel has been accepted for transport. The shop will send another message when it processes the return. Ben keeps the receipt and checks the tracking information later. He does not assume that a return is complete until he receives the appropriate confirmation."],"questions":[["Why does Ben return the jacket?",["It does not fit","It arrived empty","It is not a jacket"],0],["What must remain visible?",["The price of the jacket","The barcode","His personal notes"],1],["What does the first receipt confirm?",["Final refund","Shop inspection","Acceptance for transport"],2],["Why does Ben keep the receipt?",["It helps him track the return until confirmation","It proves a new jacket is free","He wants to use it as a ticket"],0]]},"dialogue":[["Ben","Can I drop off this return parcel here?","Можно сдать посылку на возврат здесь?"],["Worker","Yes. Do you have the return label?","Да. У вас есть этикетка?"],["Ben","Here it is. Is the barcode clear enough?","Вот. Штрихкод достаточно чёткий?"],["Worker","Yes, I'll scan it now.","Да, сейчас отсканирую."],["Ben","Does that mean the shop has received the jacket?","Это значит, что магазин получил куртку?"],["Worker","Not yet. It has been accepted for transport.","Пока нет. Посылка принята к перевозке."],["Ben","Could I have a drop-off receipt?","Можно квитанцию о сдаче?"],["Worker","Certainly. Keep it until the return is complete.","Конечно. Сохраните до завершения возврата."]],"listening":["What does the worker say is confirmed?",["The final refund","Transport acceptance","The shop's final inspection"],1],"speaking":["Describe a fictional return sequence with first, then and finally.","Ask whether a label must be printed or can be scanned.","Explain what a drop-off receipt confirms and what it does not confirm.","Give three short imperatives for checking paperwork.","Role-play asking for a receipt before leaving a counter."],"writing":["Write a short set of fictional return-label instructions.","Write a message asking whether a parcel drop-off is available.","Write a status update that distinguishes transport acceptance from final return."],"model":"I dropped off the parcel today and received a receipt. The parcel has been accepted for transport, but the shop has not confirmed the final return yet. I'll keep the receipt and check the tracking update."},{"id":"mission-v2-130","day":130,"level":"B1","title":"The task that needs a clearer priority","ru":"Задача с неясным приоритетом","goal":"Уточнить относительный приоритет задач и согласовать выполнимый срок.","version":1,"profile":"extended-v1","quality":"authored-not-independently-reviewed","grammar":{"title":"Need to / needn't / don't need to","rule":"Need to + infinitive обозначает необходимость. Don't need to / needn't + base verb означает отсутствие необходимости, а mustn't — запрет. В прошедшем: didn't need to; needn't have done — сделано, но оказалось необязательно.","pattern":"We need to finish A first; You needn't send a second copy.","example":"We don't need to complete both tasks today.","pitfall":"Не смешивай needn't do и mustn't do.","exercises":[["choice","We ___ to clarify which report is urgent.",["need","needs","needn't to"],0,"We need to."],["type","Complete: You needn't ___ (send) another copy.",["send"],"Needn't + base verb."],["order","Составь: Нам не нужно заканчивать обе задачи сегодня.",["today","tasks","both","finish","to","need","not","do","We"],"We do not need to finish both tasks today","Don't need to = отсутствие необходимости."],["choice","Which sentence means a task is prohibited?",["You needn't do it.","You mustn't do it.","You don't need to do it."],1,"Mustn't expresses prohibition."],["type","Complete: He ___ (need) to confirm the priority.",["needs"],"Third person singular."],["order","Составь: Сначала нам нужно проверить срок.",["first","deadline","the","check","to","need","We"],"We need to check the deadline first","Need to + verb."]]},"words":[["a competing deadline","конкурирующий срок"],["a priority conflict","конфликт приоритетов"],["a workload estimate","оценка нагрузки"],["a time constraint","ограничение по времени"],["a provisional schedule","предварительный график"],["a critical dependency","критическая зависимость"],["a deferrable task","задача, которую можно отложить"],["a revised due date","пересмотренный срок"],["a prioritisation decision","решение о приоритетах"],["a capacity limit","ограничение ресурсов"]],"phrases":[["Both tasks have the same proposed deadline.","У обеих задач одинаковый предполагаемый срок."],["Could you clarify which one takes priority?","Уточните, какая задача приоритетнее."],["We need to account for the missing input.","Нужно учесть отсутствующие исходные данные."],["This task can be deferred until Thursday.","Эту задачу можно отложить до четверга."],["I can complete the first report today.","Могу закончить первый отчёт сегодня."],["The second report depends on another team.","Второй отчёт зависит от другой команды."],["We shouldn't commit to an unverified deadline.","Не следует обещать неподтверждённый срок."],["You needn't prepare another draft yet.","Пока не нужно готовить ещё один черновик."],["Let's agree on a realistic sequence.","Согласуем реалистичную последовательность."],["I'll update the schedule once the priority is confirmed.","Обновлю график после подтверждения приоритета."]],"reading":{"title":"The task that needs a clearer priority","paragraphs":["A fictional support team receives two urgent requests on Monday morning. One concerns a customer-facing report that is nearly complete, while the other requires figures from a specialist who will not be available until the afternoon. Both requests have the same proposed deadline, but the team has limited capacity. The coordinator estimates the remaining work and asks the manager to clarify which deliverable takes priority. She explains that the first report can be completed independently, whereas the second depends on information that has not arrived.","The manager agrees that the first report should be completed in the morning. The second remains scheduled for later, subject to receipt of the required figures. The coordinator records the decision, rather than silently postponing one task or promising both by lunchtime. She tells the second requester what is known, what remains pending and when a revised estimate can be provided. When the figures arrive, the team checks whether the proposed deadline is still realistic. The revised schedule reflects the actual dependency rather than a wish to make every task appear on track."],"questions":[["Why can't the second report be completed immediately?",["It requires missing figures","It has already been published","It needs no work"],0],["What does the coordinator ask the manager?",["To cancel every task","Which deliverable takes priority","To change the customer name"],1],["When can the second deadline be estimated more reliably?",["Before any information is checked","Only next year","After the figures arrive and are reviewed"],2],["What principle guides the coordinator?",["Make all tasks appear finished","Base commitments on actual capacity and dependencies","Avoid telling requesters anything"],1]]},"dialogue":[["Coordinator","Both requests are due today, but we have limited capacity.","Обе задачи на сегодня, но ресурсы ограничены."],["Manager","Which one depends on information from another team?","Какая зависит от данных другой команды?"],["Coordinator","The second report. We still need the figures.","Второй отчёт. Всё ещё нужны данные."],["Manager","Then complete the first report this morning.","Тогда закончи первый отчёт утром."],["Coordinator","Do we need to promise a time for the second one?","Нужно ли обещать время для второго?"],["Manager","Not yet. Give a revised estimate when the figures arrive.","Пока нет. Дай пересмотренную оценку после получения данных."],["Coordinator","I'll record that decision and inform both requesters.","Зафиксирую решение и сообщу обоим заказчикам."],["Manager","Good. Make the dependency explicit.","Хорошо. Явно укажи зависимость."]],"listening":["When should the second estimate be given?",["When the figures arrive","Before the work is understood","After both reports are published"],0],"speaking":["Compare two fictional work requests and explain their dependencies.","Use need to and needn't to distinguish required and optional actions.","Ask a manager to clarify a conflict between two deadlines.","Give a brief status update without promising an unsupported completion time.","Role-play negotiating a realistic schedule with a requester."],"writing":["Write an email requesting a priority decision for two competing tasks.","Draft a schedule note that distinguishes confirmed and provisional deadlines.","Write a status update explaining what input is missing and what can proceed."],"model":"We can complete the customer-facing report this morning. The second report depends on figures expected later today, so its completion time remains provisional. Could you confirm that the first report takes priority? I will update the schedule after reviewing the missing input."},{"id":"mission-v2-160","day":160,"level":"B1","title":"A book ending with two interpretations","ru":"Две интерпретации финала книги","goal":"Отделить события текста от читательского толкования и обосновать мнение.","version":1,"profile":"extended-v1","quality":"authored-not-independently-reviewed","grammar":{"title":"Past continuous / Past simple","rule":"Past Continuous: was/were + -ing описывает действие в процессе в определённый момент прошлого. Past Simple описывает завершённое событие. When может вводить событие, while — параллельный процесс; выбор зависит от смысла.","pattern":"I was reading when the phone rang.","example":"While they were discussing the ending, a new member arrived.","pitfall":"Не используй was read вместо was reading для действия в процессе.","exercises":[["choice","While I ___ the final chapter, the lights went out.",["was reading","read tomorrow","am reading"],0,"Was reading describes the ongoing action."],["type","Complete: They ___ (discuss) the story when the door opened. Use past continuous.",["were discussing"],"Were + -ing."],["order","Составь: Я читал когда зазвонил телефон.",["rang","phone","the","when","reading","was","I"],"I was reading when the phone rang","Ongoing action + event."],["choice","Which describes a completed event?",["She was opening the letter when I arrived.","She opened the letter.","She is opening the letter tomorrow."],1,"Past simple describes the completed event."],["type","Complete: While he was waiting, the train ___ (arrive).",["arrived"],"Past simple for the event."],["order","Составь: Они разговаривали когда она вошла.",["entered","she","when","talking","were","They"],"They were talking when she entered","Past continuous + past simple."]]},"words":[["an ambiguous ending","неоднозначный финал"],["a fictional narrator","вымышленный рассказчик"],["a narrative clue","сюжетная подсказка"],["a point of view","точка зрения"],["a recurring image","повторяющийся образ"],["a plausible reading","правдоподобное толкование"],["a textual detail","деталь текста"],["a narrative perspective","ракурс повествования"],["a character's intention","намерение персонажа"],["an open question","открытый вопрос"]],"phrases":[["The ending leaves room for interpretation.","Финал оставляет пространство для толкования."],["The narrator describes what happened, not why.","Рассказчик описывает событие, но не причину."],["I noticed a recurring image in the story.","Я заметил повторяющийся образ в истории."],["One plausible interpretation is that she changed her mind.","Одно возможное толкование: она передумала."],["What detail supports that reading?","Какая деталь поддерживает это толкование?"],["I see it differently because of the final paragraph.","Я воспринимаю иначе из-за последнего абзаца."],["The text does not establish her intention.","Текст не устанавливает её намерение."],["We can disagree without changing the events.","Можем не соглашаться, не меняя события."],["While I was reading, I noticed another clue.","Пока я читал, заметил ещё одну подсказку."],["That remains an open question for me.","Для меня это остаётся открытым вопросом."]],"reading":{"title":"A book ending with two interpretations","paragraphs":["A reading group discusses the ending of a fictional short story about a woman who has been waiting for a letter. In the last scene, she opens the envelope, reads a few lines and puts it into a drawer. Then she walks towards the railway station. The narrator does not reveal the contents of the letter or say why the woman is leaving. One reader thinks she has decided to visit someone. Another thinks she is returning to a place from her past.","While the members were discussing the ending, a new participant arrived and asked which details supported each interpretation. The group returned to the final paragraphs and found two earlier references to the station. These references made both interpretations plausible, but they did not settle the character's intention. The leader encouraged the members to distinguish the events explicitly described from the meanings they inferred. The discussion became more interesting because nobody had to pretend that only one interpretation was possible. At the end, each member wrote a brief response that included one textual detail and one remaining uncertainty."],"questions":[["What does the narrator leave unknown?",["The contents of the letter and reason for leaving","Whether the envelope exists","The name of the railway station"],0],["What does the new participant ask for?",["A vote to ban other views","Details supporting each interpretation","A different book immediately"],1],["What do the earlier references establish?",["One interpretation is definitely true","The narrator lied","Both readings are plausible but unresolved"],2],["What makes the final discussion useful?",["Separating textual evidence from inference","Inventing a final chapter","Ignoring details in the story"],0]]},"dialogue":[["Reader A","I think she was planning to visit someone.","Думаю, она собиралась навестить кого-то."],["Reader B","I see it differently. Perhaps she was returning somewhere.","Я воспринимаю иначе. Возможно, она куда-то возвращалась."],["Reader A","What detail supports your interpretation?","Какая деталь поддерживает твоё толкование?"],["Reader B","While I was reading, I noticed the earlier station references.","Пока читал, заметил ранние упоминания вокзала."],["Reader A","Those references could fit both explanations.","Эти упоминания подходят к обоим объяснениям."],["Reader B","True. The letter's contents are not revealed.","Верно. Содержание письма не раскрыто."],["Reader A","Let's separate the events from our interpretation.","Разделим события и наше толкование."],["Reader B","Agreed. The ending remains open.","Согласен. Финал остаётся открытым."]],"listening":["What do both readers agree is unknown?",["The letter's contents","The existence of a book","The location of the club"],0],"speaking":["Summarise the fictional final scene without adding an intention.","Offer two interpretations and cite a detail for each.","Use past continuous and past simple to describe an interrupted activity.","Explain why a plausible inference is not the same as a textual fact.","Role-play disagreeing with a reader while acknowledging their evidence."],"writing":["Write a short review of the ending that separates facts and interpretation.","Write two plausible continuations of the fictional story.","Write a paragraph explaining which detail would resolve your uncertainty."],"model":"The final scene shows the woman opening the letter and walking towards the station. One plausible reading is that she intends to visit someone; another is that she is returning to a familiar place. The earlier station references support both possibilities, but the text does not establish her intention."},{"id":"mission-v2-190","day":190,"level":"B1","title":"A community class with uneven attendance","ru":"Кружок с нерегулярной посещаемостью","goal":"Объяснить наблюдаемые тенденции и предложить способы получить обратную связь.","version":1,"profile":"extended-v1","quality":"authored-not-independently-reviewed","grammar":{"title":"Quantifiers: most, several, few, a few","rule":"Most означает большинство; several — несколько; a few — немного, но некоторое количество; few — мало, с оттенком недостаточности. С неисчисляемыми: a little/little. Most of + определённая группа.","pattern":"Most learners attend; Several learners missed a class; A few responded.","example":"Few responses are not enough for a broad conclusion.","pitfall":"Не говори most of learners без the/these/my и т. п.","exercises":[["choice","___ of the registered learners attended the first class.",["Most","Much","Most of of"],0,"Most of + specified group."],["type","Complete: We received a ___ (few/little) replies.",["few"],"Replies is countable plural."],["order","Составь: Несколько участников запросили другое время.",["time","another","requested","participants","Several"],"Several participants requested another time","Several + plural noun."],["choice","Which phrase suggests insufficient responses?",["A few responses","Few responses","Several responses"],1,"Few often suggests a shortage."],["type","Complete: There is a ___ (little/few) time for feedback.",["little"],"Time is uncountable here."],["order","Составь: Большинство учащихся пришли вовремя.",["time","on","arrived","learners","Most"],"Most learners arrived on time","Most + plural noun."]]},"words":[["an attendance record","журнал посещаемости"],["a registration list","список регистрации"],["a regular participant","постоянный участник"],["a missed session","пропущенное занятие"],["a scheduling barrier","препятствие из-за расписания"],["a response rate","доля ответивших"],["an anonymous questionnaire","анонимная анкета"],["a flexible session","гибкое занятие"],["a retention pattern","характер удержания участников"],["an access difficulty","сложность доступа"]],"phrases":[["Several participants missed the second session.","Несколько участников пропустили второе занятие."],["Most of the registered learners attended initially.","Большинство зарегистрированных сначала посещали."],["We have received only a few responses.","Мы получили лишь несколько ответов."],["We don't yet know why attendance has fallen.","Пока не знаем, почему посещаемость снизилась."],["Could the timing be difficult for some learners?","Возможно, некоторым учащимся неудобно время?"],["Let's ask for anonymous feedback.","Запросим анонимную обратную связь."],["The registration list is not the same as actual attendance.","Список регистрации — не то же самое, что фактическая посещаемость."],["Few responses cannot represent everyone.","Малое число ответов не может представлять всех."],["We can test an alternative session time.","Можем попробовать другое время занятия."],["The next report should distinguish facts and possible reasons.","В следующем отчёте нужно разделить факты и возможные причины."]],"reading":{"title":"A community class with uneven attendance","paragraphs":["A community centre runs a fictional evening class for adults. Most of the people on the registration list attend the first session, but attendance falls during the following two weeks. The instructor notices that several regular participants are still attending, while some others have missed more than one session. She is tempted to conclude that the topic is not interesting. However, the attendance record only shows whether people were present; it does not explain why they were absent.","The coordinator suggests a short anonymous questionnaire that asks about timing, travel, the teaching format and access to learning materials. A few participants reply immediately, and their answers mention different difficulties. Because the response rate is low, the instructor does not treat these comments as representative of everyone. The centre tries an alternative session time for a limited period and keeps the original attendance records. At the next review, the team compares participation across both times and considers further feedback. The aim is to identify barriers, not to label absent learners as unmotivated."],"questions":[["What changed after the first session?",["Attendance fell","The centre closed","All participants changed jobs"],0],["What does the attendance record not explain?",["Whether a person attended","Why someone was absent","Which day was recorded"],1],["Why are early questionnaire replies insufficient?",["They were too detailed","They were written in English","The response rate is low"],2],["What does the team want to identify?",["Barriers to participation","People to blame","A guaranteed universal explanation"],0]]},"dialogue":[["Instructor","Several participants have missed recent sessions.","Несколько участников пропустили недавние занятия."],["Coordinator","Do we know why they couldn't attend?","Знаем, почему они не смогли прийти?"],["Instructor","Not yet. The attendance record doesn't tell us.","Пока нет. Журнал посещаемости этого не объясняет."],["Coordinator","Let's ask about timing, travel and materials.","Спросим о времени, дороге и материалах."],["Instructor","We have only a few replies so far.","Пока у нас лишь несколько ответов."],["Coordinator","Then we shouldn't generalise from those replies.","Тогда не следует обобщать на основе этих ответов."],["Instructor","Could we test an alternative session time?","Можем попробовать другое время?"],["Coordinator","Yes, and compare the results before deciding.","Да, и сравнить результаты до решения."]],"listening":["What is the proposed experiment?",["A different session time","A new registration fee","Removing the attendance record"],0],"speaking":["Describe a fictional attendance pattern using most, several and a few.","Explain why attendance does not prove motivation.","Ask three neutral feedback questions about learning access.","Propose a limited trial and describe how to assess it.","Role-play reporting a small response sample cautiously."],"writing":["Write a brief attendance summary with two limitations.","Draft four anonymous feedback questions for a fictional class.","Write a trial proposal comparing two session times without claiming success in advance."],"model":"Attendance has fallen since the first session, but the records do not explain why. We have received a few responses concerning scheduling and travel. I suggest a limited trial of an alternative session time, followed by a comparison of attendance and further feedback."},{"id":"mission-v2-220","day":220,"level":"B2","title":"The accessible event plan","ru":"Доступность мероприятия","goal":"Сформулировать требования доступности, отличить подтверждённые возможности от обещаний и сравнить варианты.","version":1,"profile":"extended-v1","quality":"authored-not-independently-reviewed","grammar":{"title":"Relative clauses and reduced clauses","rule":"Относительные придаточные уточняют объект: people who need assistance; venues which offer step-free access. Причастные сокращения возможны, когда смысл и субъект ясны: information provided in advance = information which is provided in advance.","pattern":"Visitors who request captions; instructions provided in advance.","example":"The venue, which has confirmed step-free access, is one option.","pitfall":"Не сокращай придаточное, если это создаёт неоднозначность субъекта.","exercises":[["choice","Participants ___ require captions should be offered clear information.",["who","which","where"],0,"Who refers to people."],["type","Complete: The information ___ (provide) in advance should be accurate. Use a past participle.",["provided"],"Reduced passive relative clause."],["order","Составь: Участники которым нужна помощь могут связаться с организатором.",["organiser","the","contact","can","assistance","need","who","Participants"],"Participants who need assistance can contact the organiser","Who introduces a defining relative clause."],["choice","Which sentence adds information about an already identified venue?",["The venue, which has a lift, is available.","The venue, that has a lift, is available.","The venue where has a lift is available."],0,"Non-defining which with commas."],["type","Complete: The documents ___ (publish) yesterday contain the updated plan. Use a reduced passive clause.",["published"],"Published yesterday modifies documents."],["order","Составь: Информация предоставленная заранее помогает посетителям.",["visitors","helps","advance","in","provided","Information"],"Information provided in advance helps visitors","Reduced passive relative clause."]]},"words":[["a step-free entrance","вход без ступеней"],["an accessibility requirement","требование доступности"],["a captioned presentation","презентация с субтитрами"],["an accessible format","доступный формат"],["a seating arrangement","схема размещения"],["a venue confirmation","подтверждение площадки"],["an accommodation request","запрос на адаптацию условий"],["a participation barrier","барьер участия"],["a contingency arrangement","резервная договорённость"],["an accessibility checklist","перечень проверки доступности"]],"phrases":[["We should establish which facilities are actually available.","Нужно установить, какие возможности действительно доступны."],["The venue has confirmed step-free access to the main room.","Площадка подтвердила доступ без ступеней в основной зал."],["Captioning has been requested but is not yet confirmed.","Субтитры запрошены, но пока не подтверждены."],["Information provided in advance should be specific.","Информация заранее должна быть конкретной."],["Visitors who need another format can contact the organiser.","Посетители, которым нужен другой формат, могут обратиться к организатору."],["We should avoid presenting a planned provision as an existing one.","Не следует выдавать запланированную возможность за существующую."],["The alternative venue may reduce one barrier while introducing another.","Другая площадка может устранить один барьер, создав другой."],["Could you confirm the accessible seating arrangement?","Подтвердите схему доступных мест."],["The final invitation will distinguish confirmed and pending provisions.","Итоговое приглашение разделит подтверждённые и ожидаемые возможности."],["A useful plan should be assessed with input from participants.","Полезный план нужно оценивать с учётом мнения участников."]],"reading":{"title":"The accessible event plan","paragraphs":["A fictional cultural organisation is planning a public talk. Its preferred venue has confirmed step-free access to the main room, but the organisers have not yet established whether the presentation can be captioned or whether printed information is available in an accessible format. The initial invitation describes the event as fully accessible. A reviewer challenges that description because it suggests that all relevant provisions have been verified when only one has been confirmed.","The team replaces the broad claim with a specific list of available facilities and a separate list of pending arrangements. It also provides a contact route for participants who need another format, without asking them to disclose unnecessary personal information. A second venue is considered because it may offer different facilities, although its transport connections are less convenient. The organisers compare the two options using the confirmed requirements rather than assuming that a single feature makes either venue suitable for everyone.","Before publishing the revised invitation, the coordinator asks the venue owner and the captioning provider to confirm the relevant details. The final message will state what has been verified, what remains pending and how participants can request clarification. The exercise concerns accurate communication and inclusive planning, not a claim that the fictional event satisfies every legal accessibility requirement."],"questions":[["Which provision has been confirmed initially?",["Step-free access to the main room","Captioning for every talk","All possible accessible formats"],0],["Why does the reviewer challenge the invitation?",["It is too short","It overstates verified provisions","It names a room"],1],["What trade-off might the second venue introduce?",["A guaranteed legal problem","No difference","Less convenient transport connections"],2],["What is the purpose of the revised message?",["Provide verified and pending information transparently","Promise every possible accommodation","Avoid any contact route"],0]]},"dialogue":[["Coordinator","The venue has confirmed step-free access to the main room.","Площадка подтвердила доступ без ступеней в основной зал."],["Reviewer","Has captioning been confirmed as well?","Субтитры тоже подтверждены?"],["Coordinator","No. The request is still pending.","Нет. Запрос ещё рассматривается."],["Reviewer","Then the invitation should not claim full accessibility.","Тогда приглашение не должно заявлять полную доступность."],["Coordinator","I'll list the facilities that have actually been confirmed.","Перечислю действительно подтверждённые возможности."],["Reviewer","Include a contact route for visitors who need another format.","Укажи способ связи для тех, кому нужен другой формат."],["Coordinator","We'll also review the alternative venue's transport access.","Также проверим транспортную доступность другой площадки."],["Reviewer","Good. Keep the pending arrangements separate.","Хорошо. Раздели ожидаемые договорённости."]],"listening":["Which provision is still pending?",["The event title","Captioning","The existence of the main room"],1],"speaking":["Explain the difference between confirmed and requested accessibility provisions.","Use relative and reduced relative clauses to describe fictional event facilities.","Compare two venues with different access and transport advantages.","Suggest a respectful way to ask participants what formats they need.","Deliver a two-minute event-planning summary distinguishing evidence and uncertainty."],"writing":["Write an invitation section listing confirmed facilities and pending arrangements.","Draft a comparison of two fictional venues using explicit criteria.","Write a clarification request for captioning and accessible materials without asking for unnecessary personal details."],"model":"The main room has confirmed step-free access. Captioning has been requested but is not yet confirmed. Visitors who require another format can contact the organiser. We will publish further information once the remaining provisions have been verified."},{"id":"mission-v2-250","day":250,"level":"B2","title":"A manufacturer's clarification of a disturbance export","ru":"Уточнение формата осциллограммы у производителя","goal":"Вести профессиональную переписку о формате записи, отделять наблюдение от вывода о работе защиты.","version":1,"profile":"extended-v1","quality":"authored-not-independently-reviewed","grammar":{"title":"Perfect participle clauses and evidence limits","rule":"Having + V3 описывает предшествующее завершённое действие того же субъекта: Having reviewed the export, the engineer noted a discrepancy. Не используй оборот, если действие выполнял другой субъект. Passive: Having been reviewed, the report was returned.","pattern":"Having compared the headers, the reviewer requested clarification.","example":"Having received the file, the engineer checked its documented format.","pitfall":"Не дополняй грамматический оборот техническим выводом, который не установлен.","exercises":[["choice","___ the two headers, the engineer requested clarification.",["Having compared","Having compare","Compared having"],0,"Having + past participle."],["type","Complete: Having ___ (receive) the export, she recorded its filename.",["received"],"Having + V3."],["order","Составь: Изучив метаданные инженер запросил уточнение.",["clarification","requested","engineer","the","metadata","the","reviewed","Having"],"Having reviewed the metadata the engineer requested clarification","Same subject performs both actions."],["choice","Which sentence has a correct subject relationship?",["Having checked the file, the engineer noted a discrepancy.","Having checked the file, the discrepancy appeared.","Having checking the file, the engineer noted it."],0,"The engineer checked the file."],["type","Complete: Having been ___ (review), the report was returned.",["reviewed"],"Perfect passive participle."],["order","Составь: Получив ответ рецензент обновил запись.",["record","the","updated","reviewer","the","reply","the","received","Having"],"Having received the reply the reviewer updated the record","Having + V3 precedes the later action."]]},"words":[["a disturbance export","экспорт записи аварийного процесса"],["a COMTRADE file set","набор файлов COMTRADE"],["a configuration header","заголовок конфигурации"],["a channel designation","обозначение канала"],["a sampling information field","поле сведений о дискретизации"],["a file format specification","спецификация формата файла"],["a vendor clarification","уточнение производителя"],["a recorded quantity","зарегистрированная величина"],["a data interpretation note","пояснение к интерпретации данных"],["an authorised technical review","санкционированное техническое рассмотрение"]],"phrases":[["The export contains a channel designation that requires clarification.","Экспорт содержит обозначение канала, требующее уточнения."],["Having reviewed the available metadata, we identified a documentation gap.","Изучив метаданные, мы выявили пробел в документации."],["Please confirm the meaning of this field in the exported format.","Подтвердите значение этого поля в формате экспорта."],["We are requesting clarification of the file representation only.","Мы запрашиваем уточнение только представления файла."],["The available record does not establish the physical event sequence.","Имеющаяся запись не устанавливает физическую последовательность событий."],["The original file set should be retained for review.","Исходный набор файлов следует сохранить для проверки."],["Could you identify the applicable format specification?","Укажите применимую спецификацию формата."],["We will record the manufacturer's response as supporting evidence.","Зафиксируем ответ производителя как дополнительное доказательство."],["The interpretation remains provisional pending authorised review.","Интерпретация остаётся предварительной до санкционированной проверки."],["No change to the protection configuration is implied by this request.","Запрос не подразумевает изменение конфигурации защиты."]],"reading":{"title":"A manufacturer's clarification of a disturbance export","paragraphs":["In a fictional relay protection documentation exercise, a reviewer receives a COMTRADE disturbance export together with a short report. The export contains channel designations and metadata, but the available documentation does not clearly establish the meaning of one field in the particular exported representation. Having compared the file header with the accompanying report, the reviewer records a discrepancy in the interpretation notes. She does not infer a physical event sequence or a protection malfunction merely from the unclear label.","The reviewer prepares an English-language clarification request for the equipment manufacturer's documentation contact. The request identifies the fictional file set and field, asks for the applicable format specification, and explains that the purpose is to understand the representation rather than change equipment settings. The original export and its associated metadata are retained for authorised review. The reviewer avoids sending real operational records in this language exercise; the examples use fictional identifiers and contain no actual substation configuration.","When a clarification is received, the document owner will compare it with the applicable controlled documentation and decide whether the interpretation note can be updated. Receipt of a vendor response is not itself proof of a physical operating sequence. This exercise develops professional English, evidence traceability and cautious technical communication. It provides no instruction to modify protection settings, secondary circuits or operational equipment."],"questions":[["What is the observed issue?",["An unclear field interpretation in the export","A confirmed device malfunction","A proven setting error"],0],["What does the reviewer request from the manufacturer?",["An immediate protection setting change","The applicable format specification","Permission to discard the original record"],1],["Why are original files retained?",["To replace them with guessed values","To publish private site information","For authorised traceable review"],2],["What does a vendor response establish by itself?",["Supporting clarification, not the physical operating sequence","Automatic approval of all settings","Final proof of the fault cause"],0]]},"dialogue":[["Reviewer","Having compared the headers, I found an unclear channel designation.","Сравнив заголовки, я обнаружил неясное обозначение канала."],["Colleague","Does that establish a protection malfunction?","Это устанавливает неисправность защиты?"],["Reviewer","No. We only have a documentation discrepancy.","Нет. У нас только расхождение в документации."],["Colleague","Can the manufacturer clarify the exported representation?","Может производитель уточнить представление в экспорте?"],["Reviewer","I'll request the applicable format specification.","Запрошу применимую спецификацию формата."],["Colleague","Retain the original file set and metadata for review.","Сохрани исходный набор файлов и метаданные для проверки."],["Reviewer","The interpretation remains provisional until it is reviewed.","Интерпретация остаётся предварительной до рассмотрения."],["Colleague","Good. Keep the request limited to document clarification.","Хорошо. Ограничь запрос уточнением документации."]],"listening":["What does the reviewer request?",["A new operating setting","The applicable format specification","A physical switching sequence"],1],"speaking":["Describe a fictional disturbance-export documentation gap without diagnosing equipment operation.","Use Having reviewed and Having received to explain two document-review actions.","Request clarification of a recorded quantity or channel label in professional English.","Distinguish a vendor explanation from a verified physical event sequence.","Deliver a cautious technical handover that specifies the limits of the review."],"writing":["Write a fictional manufacturer's clarification request for an unclear export field.","Draft a discrepancy note with observation, evidence requested and pending interpretation.","Write a review-status paragraph that explicitly excludes operational authorisation."],"model":"Having compared the available export header with the accompanying report, we identified an unclear channel designation. Please clarify the meaning of the field and identify the applicable format specification. The interpretation remains provisional pending authorised technical review. No operational change is implied by this documentation request."},{"id":"mission-v2-280","day":280,"level":"B2","title":"A recommendation with a reversible trial","ru":"Рекомендация с обратимым испытанием","goal":"Сравнить альтернативы, предложить измеримые критерии и определить условие пересмотра.","version":1,"profile":"extended-v1","quality":"authored-not-independently-reviewed","grammar":{"title":"Mixed conditionals","rule":"If + Past Perfect → would + base verb описывает влияние нереального прошлого на настоящее; If + Past Simple → would have + V3 может связывать постоянное условие с прошлым. Уточняй временную связь, не используй конструкции как доказательство причинности.","pattern":"If we had collected feedback earlier, we would have better evidence now.","example":"If the trial had included remote users, our current comparison might be more informative.","pitfall":"Не подменяй гипотетическую возможность установленным фактом.","exercises":[["choice","If we had collected the missing records last month, we ___ better evidence now.",["would have","would had","will had"],0,"Past counterfactual condition + present hypothetical result."],["type","Complete: If the team had agreed on the definitions, the report ___ (would / be) clearer now.",["would be"],"Present result: would + base verb."],["order","Составь: Если бы мы проверили данные раньше у нас было бы больше информации сейчас.",["now","information","more","have","would","we","earlier","data","the","checked","had","we","If"],"If we had checked the data earlier we would have more information now","Past Perfect condition + present result."],["choice","Which sentence refers to an unreal past with a present result?",["If I had saved the file, I would have it now.","If I save the file, I will have it tomorrow.","If I saved the file yesterday, I saved it."],0,"Mixed conditional links past to now."],["type","Complete: If the evidence were more complete, the committee ___ (might / have / approve) the proposal yesterday.",["might have approved"],"Hypothetical present condition and past result."],["order","Составь: Если бы мы уточнили критерии отчёт был бы яснее сейчас.",["now","clearer","be","would","report","the","criteria","the","clarified","had","we","If"],"If we had clarified the criteria the report would be clearer now","Past condition, present result."]]},"words":[["a reversible trial","обратимое испытание"],["a pre-defined outcome","заранее определённый результат"],["a stopping criterion","критерий прекращения"],["a comparison period","период сравнения"],["an implementation burden","нагрузка при внедрении"],["a stakeholder trade-off","компромисс интересов участников"],["a monitoring indicator","показатель мониторинга"],["an uncertainty register","реестр неопределённостей"],["a proportionate recommendation","соразмерная рекомендация"],["an evidence threshold","порог достаточности доказательств"]],"phrases":[["The decision should remain reversible during the trial.","Решение должно оставаться обратимым в ходе испытания."],["We need to define the outcomes before starting.","Нужно определить результаты до начала."],["The comparison period should be consistent across groups.","Период сравнения должен быть одинаковым для групп."],["A stopping criterion should reflect material adverse outcomes.","Критерий прекращения должен учитывать существенные неблагоприятные результаты."],["The evidence does not justify a permanent commitment yet.","Доказательства пока не обосновывают постоянное решение."],["If we had collected the feedback earlier, we would know more now.","Если бы собрали отзывы раньше, сейчас знали бы больше."],["The recommendation remains conditional on the agreed indicators.","Рекомендация остаётся условной и зависит от согласованных показателей."],["The implementation burden should be reported alongside the benefits.","Нагрузку внедрения следует указывать вместе с преимуществами."],["We should document unresolved assumptions separately.","Следует отдельно документировать нерешённые предположения."],["The trial result will inform the next decision rather than predetermine it.","Результат испытания поможет принять следующее решение, но не предопределит его."]],"reading":{"title":"A recommendation with a reversible trial","paragraphs":["A fictional organisation considers replacing its current training schedule with a more flexible format. Supporters believe the change could improve participation, while some instructors are concerned that preparation time would increase. The earlier feedback survey did not include enough responses from people who had stopped attending. If the organisation had collected those responses, the current discussion would have a stronger evidence base. However, the absence of that evidence does not prove either that the proposal is good or that it is unsuitable.","The project adviser recommends a reversible trial rather than an immediate permanent change. She proposes measuring completion rates, participant access, instructor preparation time and the experience of people who previously attended irregularly. The team will agree on the measurement definitions and comparison period before starting. It will also define a stopping criterion for material problems, so that a decision to reverse the trial does not depend on an improvised judgment after the results appear.","The adviser distinguishes predicted benefits from observed outcomes and asks the committee to document unresolved assumptions. At the end of the trial, the committee will assess the evidence against the agreed criteria and decide whether to extend, revise or discontinue the format. The recommendation is deliberately conditional: it protects the possibility of improvement without presenting an untested alternative as an established success."],"questions":[["Which important perspective was underrepresented in the earlier survey?",["People who had stopped attending","Every instructor who replied","The name of the programme"],0],["Why does the adviser propose a reversible trial?",["To guarantee success","To test the proposal before a permanent commitment","To avoid measuring outcomes"],1],["When will outcome definitions and comparison periods be agreed?",["After choosing favourable results","Never","Before starting"],2],["What is the final decision based on?",["The agreed criteria and observed evidence","Predicted benefits alone","The fact that a trial was proposed"],0]]},"dialogue":[["Adviser","If we had collected earlier feedback, we'd have stronger evidence now.","Если бы собрали отзывы раньше, сейчас были бы более убедительные данные."],["Chair","Does the missing feedback mean we should reject the proposal?","Отсутствие отзывов означает, что предложение нужно отклонить?"],["Adviser","Not necessarily. We need a proportionate way to test it.","Не обязательно. Нужен соразмерный способ испытать."],["Chair","What outcomes should the trial measure?","Какие результаты нужно измерять?"],["Adviser","Access, completion rates and the instructor's preparation burden.","Доступ, долю завершивших и нагрузку преподавателя."],["Chair","Can we define the stopping criteria before implementation?","Можем заранее определить критерии прекращения?"],["Adviser","Yes. The decision should remain reversible during the trial.","Да. Решение должно оставаться обратимым в ходе испытания."],["Chair","Then we'll review the evidence before making a permanent decision.","Тогда проверим доказательства до постоянного решения."]],"listening":["When should stopping criteria be defined?",["After finding a favourable outcome","Before implementation","Only after a permanent decision"],1],"speaking":["Explain how missing past feedback affects a present recommendation using a mixed conditional.","Propose four measurable trial outcomes for the fictional training schedule.","Explain why a reversible decision is different from a guarantee of success.","Present the interests of participants and instructors without dismissing either.","Deliver a two-minute recommendation with review and stopping conditions."],"writing":["Write a conditional recommendation for a reversible training trial.","Draft a short evidence and uncertainty register for the fictional proposal.","Write a balanced evaluation plan that states criteria before observing outcomes."],"model":"If the earlier survey had included people who stopped attending, our current evidence would be more informative. I recommend a reversible trial with pre-defined access, completion and preparation-time measures. The stopping criteria and comparison period should be agreed before implementation. The observed outcomes will inform the subsequent decision."}]);
